{"file_path":"src/snapshot.js","content":"/** Reading a digest snapshot file, as `plan` consumes it. */

import { readFileSync } from 'node:fs'
import { splitLines } from './parse.js'

const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot, carrying the 1-based snapshot line, or null when it names none. */
export class SnapshotError extends Error {
  /**
   * @param {number|null} line - the 1-based snapshot line, or null when the failure names no line.
   * @param {string} message - the message the specification words, without the `error: ` prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'SnapshotError'
    this.line = line
  }
}

/**
 * Read a digest snapshot into the digests it records.
 * @param {string} path - the snapshot file's path.
 * @returns {Map<string, string>} the recorded digest by path.
 */
export function readSnapshot(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new SnapshotError(null, `cannot read snapshot ${path}`)
  }
  const digests = new Map()
  for (const [index, raw] of splitLines(text).entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(line, 'expected <path> <digest>')
    const [recordedPath, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(line, `invalid digest ${digest}`)
    if (digests.has(recordedPath)) throw new SnapshotError(line, `path ${recordedPath} is recorded twice`)
    digests.set(recordedPath, digest)
  }
  return digests
}
"}

