{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { splitDocuments } from './input.js'
import { computeBlocks } from './regions.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('error: usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const documents = splitDocuments(input)
  if (documents === null) {
    fail('error: expected three parts separated by %%%')
    return
  }
  const [mine, base, theirs] = documents

  const blocks = computeBlocks(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const block of blocks) {
      if (block.type === 'conflict') {
        conflict = true
        out.push(`conflict mine=${block.mine.length} base=${block.base.length} theirs=${block.theirs.length}`)
      } else {
        out.push(`${block.type} ${block.lines.length}`)
      }
    }
  } else {
    const includeBase = mode === 'merge'
    for (const block of blocks) {
      if (block.type === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine')
        for (const line of block.mine) out.push(line)
        if (includeBase) {
          out.push('||||||| base')
          for (const line of block.base) out.push(line)
        }
        out.push('=======')
        for (const line of block.theirs) out.push(line)
        out.push('>>>>>>> theirs')
      } else {
        for (const line of block.lines) out.push(line)
      }
    }
  }

  const text = out.length > 0 ? out.join('\n') + '\n' : ''
  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

