/** A line that defines a link label: `[label]: url`, trimmed, with the url required non-empty. */
export const DEFINITION = /^\[([^\]]+)\]:\s+(\S.*)$/u

/**
 * Normalize a label the way the specification asks: trimmed, internal whitespace runs collapsed to one space, lowercased.
 * @param {string} label - the label as written.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replace(/\s+/gu, ' ').toLowerCase()
}
"}

