{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-47XClT/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator, collectDeps } from './evaluator.js'
import { parseFormula } from './parser.js'
import { formatAddress } from './address.js'
import { formatValue } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

async function readStdinAsync() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks.map((c) => (Buffer.isBuffer(c) ? c : Buffer.from(c)))).toString('utf8')
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = args[0]

  const input = await readStdinAsync()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const sortedKeys = [...cells.keys()].sort((ka, kb) => {
    const a = cells.get(ka)
    const b = cells.get(kb)
    if (a.col !== b.col) return a.col - b.col
    return a.row - b.row
  })

  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const key of sortedKeys) {
      const cellData = cells.get(key)
      const value = evaluator.evalKey(key)
      out.push(`${formatAddress(cellData)}=${formatValue(value)}`)
    }
  } else {
    for (const key of sortedKeys) {
      const cellData = cells.get(key)
      let names = []
      if (cellData.content.startsWith('=')) {
        const ast = parseFormula(cellData.content.slice(1))
        if (ast !== null) {
          const set = new Map()
          collectDeps(ast, set)
          names = [...set.values()].sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
        }
      }
      const suffix = names.map((a) => ' ' + formatAddress(a)).join('')
      out.push(`${formatAddress(cellData)}:${suffix}`)
    }
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

