{"file_path":"src/pack.js","content":"import { computePriority } from './schedule.js'

/**
 * Simulate the build graph on `workerCount` workers, per the greedy priority
 * rule described in the task prompt.
 */
export function packSchedule(tasks, workerCount) {
  const priority = computePriority(tasks)
  const names = [...tasks.keys()]

  const freeAt = new Array(workerCount).fill(0)
  const workerLines = Array.from({ length: workerCount }, () => [])
  const finishTime = new Map()
  const remaining = new Set(names)

  let currentTime = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of remaining) {
        const task = tasks.get(name)
        let ready = true
        for (const dep of task.deps) {
          const f = finishTime.get(dep)
          if (f === undefined || f > currentTime) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const task = tasks.get(best)
      const s = currentTime
      const f = s + task.cost
      finishTime.set(best, f)
      freeAt[freeWorker] = f
      workerLines[freeWorker].push(`${best}@${s}-${f}`)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (freeAt[i] > currentTime) next = Math.min(next, freeAt[i])
    }
    currentTime = next
  }

  let makespan = 0
  for (const f of finishTime.values()) makespan = Math.max(makespan, f)

  return { workerLines, makespan }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError, CycleError } from './errors.js'
import { parseGraph } from './parser.js'
import { detectCycle } from './cycle.js'
import { computeSchedule } from './schedule.js'
import { packSchedule } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { type: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError(2, 'error: workers must be a positive integer')
    }
    return { type: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(2, USAGE)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require_fs()
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // Lazily require to keep this module ESM-friendly while still using a
  // synchronous read of stdin.
  return globalThis.__fs ?? (globalThis.__fs = require('node:fs'))
}

function main() {
  const argv = process.argv.slice(2)
  const mode = parseArgs(argv)

  const text = readStdin()
  const { tasks } = parseGraph(text)
  detectCycle(tasks)

  const lines = []

  if (mode.type === 'waves') {
    const { names, depth, total } = computeSchedule(tasks)
    const byWave = new Map()
    for (const name of names) {
      const d = depth.get(name)
      if (!byWave.has(d)) byWave.set(d, [])
      byWave.get(d).push(name)
    }
    const waveIndices = [...byWave.keys()].sort((a, b) => a - b)
    for (const w of waveIndices) {
      lines.push(`wave ${w}: ${byWave.get(w).join(' ')}`)
    }
    lines.push(`total ${total}`)
  } else if (mode.type === 'explain') {
    const { names, depth, start, finish, total } = computeSchedule(tasks)
    for (const name of names) {
      lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
    }
    lines.push(`total ${total}`)
  } else if (mode.type === 'pack') {
    const { workerLines, makespan } = packSchedule(tasks, mode.workers)
    for (let i = 0; i < workerLines.length; i++) {
      const items = workerLines[i]
      lines.push(items.length > 0 ? `worker ${i}: ${items.join(' ')}` : `worker ${i}:`)
    }
    lines.push(`makespan ${makespan}`)
  }

  process.stdout.write(lines.join('\n') + '\n')
}

try {
  main()
} catch (err) {
  if (err instanceof CliError || err instanceof CycleError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  }
  throw err
}
"}

