// tables, and table headers.
import { makeTable, makeArray, ParseError } from './nodes.js'

function lastTableOf(node) {
  // "Walking through an array of tables uses its last element."
  return node.items[node.items.length - 1]
}

// Assigns `value` into `table` at `segments` (a dotted-name path), creating
// intermediate tables as the dots walk through. `prefix` is the path from
// the document root to `table`, used only to build full error paths.
export function assignDottedKey(table, segments, value, prefix, lineNo) {
  let current = table
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    const isLast = i === segments.length - 1
    const pathSoFar = prefix.concat(segments.slice(0, i + 1)).join('.')
    if (isLast) {
      if (current.map.has(seg)) {
        throw new ParseError(lineNo, `key ${pathSoFar} is defined twice`)
      }
      current.map.set(seg, value)
      return
    }
    let child = current.map.get(seg)
    if (child === undefined) {
      child = makeTable()
      current.map.set(seg, child)
    } else if (child.kind === 'table') {
      // fine, descend
    } else if (child.kind === 'array' && child.isTableArray) {
      child = lastTableOf(child)
    } else {
      throw new ParseError(lineNo, `${pathSoFar} is not a table`)
    }
    current = child
  }
}

// Resolves the target table for a `[name]` header, creating tables along
// the way, and marks it as header-defined.
export function resolveTableHeader(root, segments, lineNo) {
  let current = root
  const path = []
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    path.push(seg)
    const isLast = i === segments.length - 1
    let child = current.map.get(seg)
    if (child === undefined) {
      child = makeTable()
      current.map.set(seg, child)
    } else if (child.kind === 'array' && child.isTableArray) {
      child = lastTableOf(child)
    } else if (child.kind !== 'table') {
      throw new ParseError(lineNo, `${path.join('.')} is not a table`)
    }
    if (isLast) {
      if (child.headerDefined) {
        throw new ParseError(lineNo, `table ${path.join('.')} is defined twice`)
      }
      child.headerDefined = true
    }
    current = child
  }
  return current
}

// Resolves (creating/appending as needed) the target table for a
// `[[name]]` header.
export function resolveArrayTableHeader(root, segments, lineNo) {
  let current = root
  const path = []
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    path.push(seg)
    const isLast = i === segments.length - 1
    let child = current.map.get(seg)
    if (!isLast) {
      if (child === undefined) {
        child = makeTable()
        current.map.set(seg, child)
      } else if (child.kind === 'array' && child.isTableArray) {
        child = lastTableOf(child)
      } else if (child.kind !== 'table') {
        throw new ParseError(lineNo, `${path.join('.')} is not a table`)
      }
      current = child
      continue
    }
    // last segment: must become/be an array of tables
    if (child === undefined) {
      child = makeArray(true)
      current.map.set(seg, child)
    } else if (!(child.kind === 'array' && child.isTableArray)) {
      throw new ParseError(lineNo, `${path.join('.')} is not an array of tables`)
    }
    const fresh = makeTable()
    child.items.push(fresh)
    current = fresh
  }
  return current
}
