{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-I3ZF0R/src/document.js","content":"// Top-level line-oriented parsing: blank/comment lines, headers, and
// key = value assignments.
import { makeTable, ParseError } from './nodes.js'
import { LineState, parseDottedName } from './lexer.js'
import { parseValue } from './values.js'
import { assignDottedKey, resolveTableHeader, resolveArrayTableHeader } from './assign.js'

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let current = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const text = lines[i]

    let j = 0
    while (j < text.length && (text[j] === ' ' || text[j] === '\t')) j++
    if (j === text.length) continue // blank line
    const first = text[j]
    if (first === '#' || first === ';') continue // comment-only line

    const state = new LineState(text, lineNo)
    state.pos = j

    if (first === '[') {
      const arrayHeader = text[j + 1] === '['
      state.pos += arrayHeader ? 2 : 1
      state.skipWs()
      const segments = parseDottedName(state)
      state.skipWs()
      if (arrayHeader) {
        if (state.peek() !== ']' || text[state.pos + 1] !== ']') {
          state.fail('unterminated table header')
        }
        state.pos += 2
      } else {
        if (state.peek() !== ']') {
          state.fail('unterminated table header')
        }
        state.pos += 1
      }
      state.skipWs()
      if (!state.atCommentOrEnd()) {
        state.fail('trailing text after a table header')
      }
      current = arrayHeader
        ? resolveArrayTableHeader(root, segments, lineNo)
        : resolveTableHeader(root, segments, lineNo)
      currentPath = segments
      continue
    }

    // <dotted name> = <value>
    const segments = parseDottedName(state)
    state.skipWs()
    if (state.atCommentOrEnd() || state.peek() !== '=') {
      state.fail('expected key = value')
    }
    state.pos += 1
    state.skipWs()
    const selfPath = currentPath.concat(segments)
    const value = parseValue(state, selfPath)
    assignDottedKey(current, segments, value, currentPath, lineNo)
    state.skipWs()
    if (!state.atCommentOrEnd()) {
      state.fail('trailing text after a value')
    }
  }

  return root
}

export { ParseError }
"}

