/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { EnvError, parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { SETTINGS, coerce, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Read and parse one INI file, refusing a missing file or a grammar failure at its own position. */
function readIni(path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return parseIni(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** Refuse the first key an INI file sets that the schema does not know, in the order the file writes them. */
function checkKnown(path, values) {
  for (const [key, entry] of values) {
    if (setting(key) === undefined) fail(`${path}:${entry.line}:${entry.column}: unknown setting ${key}`)
  }
}

/** One INI layer for `dump`/`get`, leniently: no schema check. */
function iniLayer(name, path) {
  return { name, values: readIni(path) }
}

/** One INI layer for `load`/`origin`: checked against the schema right after it parses. */
function checkedIniLayer(name, path) {
  const values = readIni(path)
  checkKnown(path, values)
  return { name, values }
}

/** The environment layer, read from standard input. */
function envLayer() {
  const text = readFileSync(0, 'utf8')
  try {
    return { name: 'env', values: parseEnv(text) }
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []

if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const layers = [checkedIniLayer('base', argv[1]), checkedIniLayer('site', argv[2]), envLayer()]
  const paths = { base: argv[1], site: argv[2], env: '<stdin>' }
  const values = merge(layers)

  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const entry = values.get(declared.key)
      out.push(`${declared.key} ${entry ? entry.layer : 'default'}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const entry = values.get(declared.key)
      const text = entry ? entry.text : setting(declared.key).default
      try {
        out.push(`${declared.key}=${coerce(declared, text)}`)
      } catch (error) {
        const where = entry ? `${paths[entry.layer]}:${entry.line}:${entry.column}` : paths.base
        fail(`${where}: ${error.message}`)
      }
    }
  }
}

