 * RFC 3986 URI reference parsing, normalization and resolution.
 */

export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function asciiLower(str) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i)
    out += c >= 65 && c <= 90 ? String.fromCharCode(c + 32) : str[i]
  }
  return out
}

function isHexDigit(c) {
  return c !== undefined && /[0-9A-Fa-f]/.test(c)
}

function hasInvalidPercent(str) {
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      if (!isHexDigit(str[i + 1]) || !isHexDigit(str[i + 2])) return true
      i += 2
    }
  }
  return false
}

const UNRESERVED = /[A-Za-z0-9\-._~]/

function applyPercent(str) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      const hex = (str[i + 1] + str[i + 2]).toUpperCase()
      const code = parseInt(hex, 16)
      const ch = String.fromCharCode(code)
      out += UNRESERVED.test(ch) ? ch : '%' + hex
      i += 2
    } else {
      out += str[i]
    }
  }
  return out
}

/**
 * Parse a URI reference into { scheme, authority, path, query, fragment }.
 * Absent components are undefined; present-but-empty components are ''.
 * `path` is always present (possibly '').
 */
export function parseReference(str) {
  let rest = str
  let scheme

  let idx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':' || c === '/' || c === '?' || c === '#') {
      idx = i
      break
    }
  }
  if (idx !== -1 && rest[idx] === ':') {
    scheme = rest.slice(0, idx)
    rest = rest.slice(idx + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === '?' || c === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query
  if (rest.startsWith('?')) {
    let end = rest.length
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] === '#') {
        end = i
        break
      }
    }
    query = rest.slice(1, end)
    rest = rest.slice(end)
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Split an authority string into { userinfo, host, port }. */
export function decomposeAuthority(authority) {
  let userinfo
  let rest = authority
  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  const bracket = rest.lastIndexOf(']')
  let colon = -1
  for (let i = bracket + 1; i < rest.length; i++) {
    if (rest[i] === ':') {
      colon = i
      break
    }
  }
  let host, port
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  } else {
    host = rest
  }
  return { userinfo, host, port }
}

