  if (authority !== undefined) {
    ;({ userinfo, host, port } = decomposeAuthority(authority))
  }
  let path = comp.path
  let query = comp.query
  let fragment = comp.fragment

  const checks = [
    ['path', path],
    ['userinfo', userinfo],
    ['host', host],
    ['query', query],
    ['fragment', fragment],
  ]
  for (const [name, val] of checks) {
    if (val !== undefined && hasInvalidPercent(val)) {
      throw new UriError(`the ${name} has a truncated percent-encoding`)
    }
  }

  path = applyPercent(path)
  if (userinfo !== undefined) userinfo = applyPercent(userinfo)
  if (host !== undefined) host = applyPercent(host)
  if (port !== undefined) port = applyPercent(port)
  if (query !== undefined) query = applyPercent(query)
  if (fragment !== undefined) fragment = applyPercent(fragment)

  if (host !== undefined) host = asciiLower(host)

  if (port !== undefined) {
    const def = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || (def !== undefined && port === def)) {
      port = undefined
    }
  }

  path = removeDotSegments(path)

  if (authority !== undefined) {
    authority = recomposeAuthority({ userinfo, host, port })
    if (path === '') path = '/'
  }

  return { scheme, authority, path, query, fragment }
}

export function normalize(str) {
  return serialize(normalizeComponents(parseReference(str)))
}

function mergePaths(baseComp, refPath) {
  if (baseComp.authority !== undefined && baseComp.path === '') {
    return '/' + refPath
  }
  const idx = baseComp.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return baseComp.path.slice(0, idx + 1) + refPath
}

/** RFC 3986 section 5.2.2 (strict). Returns un-normalized target components. */
export function resolveReference(baseComp, refComp) {
  const target = {}
  if (refComp.scheme !== undefined) {
    target.scheme = refComp.scheme
    target.authority = refComp.authority
    target.path = removeDotSegments(refComp.path)
    target.query = refComp.query
    target.fragment = refComp.fragment
  } else {
    target.scheme = baseComp.scheme
    if (refComp.authority !== undefined) {
      target.authority = refComp.authority
      target.path = removeDotSegments(refComp.path)
      target.query = refComp.query
      target.fragment = refComp.fragment
    } else {
      target.authority = baseComp.authority
      if (refComp.path === '') {
        target.path = baseComp.path
        target.query = refComp.query !== undefined ? refComp.query : baseComp.query
      } else {
        if (refComp.path.startsWith('/')) {
          target.path = removeDotSegments(refComp.path)
        } else {
          target.path = removeDotSegments(mergePaths(baseComp, refComp.path))
        }
        target.query = refComp.query
      }
      target.fragment = refComp.fragment
    }
  }
  return target
}

export function resolve(baseStr, refStr) {
  const baseComp = parseReference(baseStr)
  if (baseComp.scheme === undefined) {
    throw new UriError('the base has no scheme')
  }
  const refComp = parseReference(refStr)
  const target = resolveReference(baseComp, refComp)
  return serialize(normalizeComponents(target))
}
"}

