import { normalize, resolve, UriError } from './uri.js'

function usageError() {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    usageError()
    return
  }
  const mode = args[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let records
  if (input === '') {
    records = []
  } else {
    records = input.split('\n')
    if (records[records.length - 1] === '') records.pop()
  }

  const outputs = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    const record = records[i]
    try {
      let outLine
      if (mode === 'normalize') {
        outLine = normalize(record)
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const baseStr = record.slice(0, spaceIdx)
        const refStr = record.slice(spaceIdx + 1)
        outLine = resolve(baseStr, refStr)
      }
      outputs.push(outLine)
    } catch (e) {
      if (e instanceof UriError) {
        process.stderr.write(`error: line ${lineNumber}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
