    if (!tasks.has(entry.name)) {
      throw new CliError(2, `unknown task ${entry.name}`)
    }
    for (const dep of entry.deps) {
      if (!tasks.has(dep)) {
        throw new CliError(2, `unknown task ${dep}`)
      }
