/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { tokenize, ScanError } from './scanner.js'

const USAGE = 'error: usage: cli.js tokens|stats\n'
const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write(USAGE)
    process.exit(2)
  }
  const mode = args[0]

  let src
  try {
    src = readFileSync(0, 'utf8')
  } catch (e) {
    src = ''
  }

  let tokens
  try {
    tokens = tokenize(src)
  } catch (e) {
    if (e instanceof ScanError) {
      process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  let out = ''
  if (mode === 'tokens') {
    for (const t of tokens) {
      out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
    }
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind] += 1
    for (const k of KIND_ORDER) {
      out += `${k} ${counts[k]}\n`
    }
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

