{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { merge } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function parseDocuments(input) {
  let lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const parts = []
  let current = []
  for (const line of lines) {
    if (line === '%%%') {
      parts.push(current)
      current = []
    } else {
      current.push(line)
    }
  }
  parts.push(current)

  if (parts.length !== 3) return null
  return parts
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatMerge(segments, includeBase) {
  let conflict = false
  const out = []
  for (const segment of segments) {
    if (segment.type === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      for (const line of segment.mineLines) out.push(line)
      if (includeBase) {
        out.push('||||||| base')
        for (const line of segment.baseLines) out.push(line)
      }
      out.push('=======')
      for (const line of segment.theirsLines) out.push(line)
      out.push('>>>>>>> theirs')
    } else {
      for (const line of segment.lines) out.push(line)
    }
  }
  return { text: out.length ? out.map(l => `${l}\n`).join('') : '', conflict }
}

function formatRegions(segments) {
  let conflict = false
  const out = []
  for (const segment of segments) {
    if (segment.type === 'conflict') {
      conflict = true
      out.push(`conflict mine=${segment.mineLines.length} base=${segment.baseLines.length} theirs=${segment.theirsLines.length}`)
    } else {
      out.push(`${segment.type} ${segment.lines.length}`)
    }
  }
  return { text: out.length ? out.map(l => `${l}\n`).join('') : '', conflict }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const input = readStdin()
  const parts = parseDocuments(input)
  if (parts === null) {
    fail('expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const segments = merge(mine, base, theirs)

  let result
  if (mode === 'merge') result = formatMerge(segments, true)
  else if (mode === 'merge2') result = formatMerge(segments, false)
  else result = formatRegions(segments)

  process.stdout.write(result.text)
  process.exit(result.conflict ? 1 : 0)
}

main()
"}

