{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-OKoEdQ/src/parse.js","content":"/**
 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

/**
 * Parses the raw election text into `{ candidates, ballots }`, where
 * `candidates` is an array of names in declaration order and `ballots` is an
 * array of `{ count, names }`. Throws `ParseError` on any malformed input.
 */
export function parseElection(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail('expected candidates <name>...', lineNumber)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNumber)
        }
        seen.add(name)
      }
      candidates = names
      for (const name of names) candidateSet.add(name)
    } else if (word === 'ballot') {
      if (candidates === null) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        fail('expected ballot <count> <candidate>...', lineNumber)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        fail('count must be a positive integer', lineNumber)
      }
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count: Number.parseInt(countStr, 10), names })
    } else {
      fail(`unknown directive ${word}`, lineNumber)
    }
  }

  if (candidates === null) {
    fail('no candidates')
  }

  return { candidates, ballots }
}
"}

