{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-OKoEdQ/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { countRounds } from './count.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatRoundLine(roundNumber, round) {
  const entries = [...round.counts.entries()]
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const location = err.line === undefined ? '' : `line ${err.line}: `
      process.stderr.write(`error: ${location}${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = countRounds(election)

  const out = []
  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      const round = rounds[i]
      out.push(formatRoundLine(i + 1, round))
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    }
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

