{"file_path":"src/parse.js","content":"import { lineError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function isValidToken(token) {
  return NAME_RE.test(token)
}

function parseField(token, fieldName, min, lineNumber) {
  if (!INT_RE.test(token)) {
    throw lineError(lineNumber, `${fieldName} must be an integer of at least ${min}`)
  }
  const value = BigInt(token)
  if (value < BigInt(min)) {
    throw lineError(lineNumber, `${fieldName} must be an integer of at least ${min}`)
  }
  return value
}

/**
 * Parses the whole limiter file text into a structured program.
 * Throws a CliError on the first problem found.
 */
export function parseProgram(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const policies = new Map() // name -> { kind: 'bucket'|'window', ... }
  const routes = [] // { prefix, policyNames: [] }
  const routePrefixes = new Set()
  const events = [] // { tick: BigInt, key }

  let sawEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue

    const tokens = raw.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (sawEvent) {
        throw lineError(lineNumber, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw lineError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityTok, refillTok, perTok] = tokens
      if (!isValidToken(name)) {
        throw lineError(lineNumber, `invalid policy name ${name}`)
      }
      const capacity = parseField(capacityTok, 'capacity', 1, lineNumber)
      const refill = parseField(refillTok, 'refill', 0, lineNumber)
      const per = parseField(perTok, 'per', 1, lineNumber)
      if (policies.has(name)) {
        throw lineError(lineNumber, `policy ${name} is declared twice`)
      }
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw lineError(lineNumber, 'expected window <name> <limit> <span>')
      }
      const [, name, limitTok, spanTok] = tokens
      if (!isValidToken(name)) {
        throw lineError(lineNumber, `invalid policy name ${name}`)
      }
      const limit = parseField(limitTok, 'limit', 0, lineNumber)
      const span = parseField(spanTok, 'span', 1, lineNumber)
      if (policies.has(name)) {
        throw lineError(lineNumber, `policy ${name} is declared twice`)
      }
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw lineError(lineNumber, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!isValidToken(prefix)) {
        throw lineError(lineNumber, `invalid route prefix ${prefix}`)
      }
      if (routePrefixes.has(prefix)) {
        throw lineError(lineNumber, `prefix ${prefix} is routed twice`)
      }
      for (const policyName of policyNames) {
        if (!policies.has(policyName)) {
          throw lineError(lineNumber, `unknown policy ${policyName}`)
        }
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw lineError(lineNumber, 'expected event <tick> <key>')
      }
      const [, tickTok, key] = tokens
      const tick = parseField(tickTok, 'tick', 0, lineNumber)
      if (lastTick !== null && tick < lastTick) {
        throw lineError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      if (!isValidToken(key)) {
        throw lineError(lineNumber, `invalid key ${key}`)
      }
      lastTick = tick
      sawEvent = true
      events.push({ tick, key })
    } else {
      throw lineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

