import { IniError, indent, valuePosition } from './ini.js'
import { SETTINGS } from './schema.js'

/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, path: string | null, values: Map<string, {text: string, line: number, column: number}>}[]} layers
 *   - the layers, weakest first.
 * @returns {Map<string, {text: string, line: number, column: number, layer: string, path: string | null}>}
 *   each key's winning entry, carrying the layer that set it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) {
      merged.set(key, { ...entry, layer: layer.name, path: layer.path })
    }
  }
  return merged
}

const NAME_TO_KEY = new Map(SETTINGS.map(declared => [`CONF_${declared.key.toUpperCase().replace(/\./gu, '_')}`, declared.key]))

/**
 * Parse an environment layer's text (one `NAME=VALUE` per line) into its settings.
 * @param {string} text - the whole standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each known setting's raw
 *   value and the position it was written at, in the order the input writes them.
 * @throws {IniError} on the first line the grammar refuses.
 */
export function parseEnv(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const column = indent(raw)
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, column, 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
