{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986,
 * following the specific rules of this task.
 */

export class ComponentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/**
 * Parse a URI reference into { scheme, authority, path, query, fragment }.
 * scheme, authority, query and fragment are `undefined` when absent, or a
 * (possibly empty) string when present. path is always a string.
 */
export function parseReference(s) {
  let i = 0
  let scheme
  let j = 0
  while (j < s.length && s[j] !== ':' && s[j] !== '/' && s[j] !== '?' && s[j] !== '#') j++
  if (j < s.length && s[j] === ':') {
    scheme = s.slice(0, j)
    i = j + 1
  }

  let authority
  if (s.slice(i, i + 2) === '//') {
    i += 2
    let k = i
    while (k < s.length && s[k] !== '/' && s[k] !== '?' && s[k] !== '#') k++
    authority = s.slice(i, k)
    i = k
  }

  let path
  {
    let k = i
    while (k < s.length && s[k] !== '?' && s[k] !== '#') k++
    path = s.slice(i, k)
    i = k
  }

  let query
  if (i < s.length && s[i] === '?') {
    i++
    let k = i
    while (k < s.length && s[k] !== '#') k++
    query = s.slice(i, k)
    i = k
  }

  let fragment
  if (i < s.length && s[i] === '#') {
    i++
    fragment = s.slice(i)
  }

  return { scheme, authority, path, query, fragment }
}

/** Split an authority string into { userinfo, host, port }. */
export function parseAuthority(auth) {
  let userinfo
  let hostport = auth
  const atIdx = auth.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = auth.slice(0, atIdx)
    hostport = auth.slice(atIdx + 1)
  }

  const bracketIdx = hostport.lastIndexOf(']')
  const searchStart = bracketIdx + 1
  const colonIdx = hostport.indexOf(':', searchStart)
  let host, port
  if (colonIdx !== -1) {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  } else {
    host = hostport
  }

  return { userinfo, host, port }
}

function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
}

function isUnreserved(ch) {
  return (
    (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') ||
    (ch >= '0' && ch <= '9') ||
    ch === '-' ||
    ch === '.' ||
    ch === '_' ||
    ch === '~'
  )
}

/**
 * Uppercase the hex digits of every %XX triplet, and replace the triplet
 * with the character it encodes when that character is unreserved.
 * Throws ComponentError(name) when a `%` is not followed by two hex digits.
 */
export function fixPercentEncoding(s, name) {
  let result = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      if (i + 2 >= s.length || !isHexDigit(s[i + 1]) || !isHexDigit(s[i + 2])) {
        throw new ComponentError(name)
      }
      const hex = s.slice(i + 1, i + 3).toUpperCase()
      const code = parseInt(hex, 16)
      const ch = String.fromCharCode(code)
      if (isUnreserved(ch)) {
        result += ch
      } else {
        result += '%' + hex
      }
      i += 2
    } else {
      result += s[i]
    }
  }
  return result
}

/** Lowercase only ASCII A-Z. */
export function asciiLower(s) {
  return s.replace(/[A-Z]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) + 32))
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx = 0
      if (input[0] === '/') idx = 1
      let nextSlash = input.indexOf('/', idx)
      if (nextSlash === -1) nextSlash = input.length
      output += input.slice(0, nextSlash)
      input = input.slice(nextSlash)
    }
  }
  return output
}

function removeLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}

/**
 * Normalize a parsed reference { scheme, authority, path, query, fragment }
 * (authority a string or undefined) and serialize it back to text.
 */
export function normalizeComponents(parsed) {
  let scheme = parsed.scheme
  if (scheme !== undefined) scheme = asciiLower(scheme)

  let userinfo, host, port
  if (parsed.authority !== undefined) {
    ;({ userinfo, host, port } = parseAuthority(parsed.authority))
  }

  if (userinfo !== undefined) userinfo = fixPercentEncoding(userinfo, 'userinfo')
  if (host !== undefined) host = fixPercentEncoding(host, 'host')
  let path = fixPercentEncoding(parsed.path, 'path')
  let query = parsed.query !== undefined ? fixPercentEncoding(parsed.query, 'query') : undefined
  let fragment = parsed.fragment !== undefined ? fixPercentEncoding(parsed.fragment, 'fragment') : undefined

  if (host !== undefined) host = asciiLower(host)

  if (port !== undefined) {
    const defaultPort = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || port === defaultPort) port = undefined
  }

  path = removeDotSegments(path)

  if (parsed.authority !== undefined && path === '') path = '/'

  let result = ''
  if (scheme !== undefined) result += scheme + ':'
  if (parsed.authority !== undefined) {
    result += '//'
    if (userinfo !== undefined) result += userinfo + '@'
    result += host
    if (port !== undefined) result += ':' + port
  }
  result += path
  if (query !== undefined) result += '?' + query
  if (fragment !== undefined) result += '#' + fragment
  return result
}

/** Normalize a URI reference string. */
export function normalizeReference(s) {
  return normalizeComponents(parseReference(s))
}

function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolve reference `ref` against `base` (both parsed references) per
 * RFC 3986 section 5.2.2, strict form. Returns a normalized string.
 */
export function resolveReference(base, ref) {
  const target = {}

  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    target.scheme = base.scheme
    if (ref.authority !== undefined) {
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      target.authority = base.authority
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== undefined ? ref.query : base.query
      } else {
        if (ref.path.startsWith('/')) {
          target.path = removeDotSegments(ref.path)
        } else {
          target.path = removeDotSegments(mergePaths(base, ref.path))
        }
        target.query = ref.query
      }
    }
  }
  target.fragment = ref.fragment

  return normalizeComponents(target)
}
"}

