      const c = peek()
      if (isDigit(c)) {
        advance()
        count++
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && isDigit(peek(1))) {
        advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return count
  }

