{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-ZCJO32/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, sortedKeys, SheetError } from './sheet.js'
import { parseAddress } from './address.js'
import { makeEvaluator, collectDeps } from './evaluate.js'
import { formatValue } from './values.js'

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) {
      process.stderr.write(err.message)
      process.exit(2)
    }
    throw err
  }

  const keys = sortedKeys(cells)
  const lines = []

  if (mode === 'values') {
    const evaluator = makeEvaluator(cells)
    for (const key of keys) {
      const val = evaluator.evalCell(key)
      lines.push(`${key}=${formatValue(val)}`)
    }
  } else {
    for (const key of keys) {
      const cell = cells.get(key)
      let depKeys = []
      if (cell.content.startsWith('=')) {
        const evaluator = makeEvaluator(cells)
        const info = evaluator.getInfo(key)
        if (info.kind === 'formula') {
          depKeys = [...collectDeps(info.ast)]
          depKeys.sort((ka, kb) => {
            const a = parseAddress(ka)
            const b = parseAddress(kb)
            return a.col !== b.col ? a.col - b.col : a.row - b.row
          })
        }
      }
      lines.push(`${key}:` + depKeys.map((d) => ` ${d}`).join(''))
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

