{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-ZaXj8F/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph, CliError } from './parse.js'
import { findCycle, computeSchedule } from './graph.js'
import { pack } from './pack.js'

const WORKERS_RE = /^[1-9]\d*$/

function usageError() {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function fail(message, exitCode) {
  process.stderr.write(message + '\n')
  process.exit(exitCode)
}

async function main() {
  const argv = process.argv.slice(2)

  let mode
  let workers

  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    mode = argv[0]
  } else if (argv.length === 2 && argv[0] === 'pack') {
    mode = 'pack'
    if (!WORKERS_RE.test(argv[1])) {
      fail('error: workers must be a positive integer', 2)
    }
    workers = parseInt(argv[1], 10)
  } else {
    usageError()
    return
  }

  const input = await readStdin()

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseGraph(input))
  } catch (e) {
    if (e instanceof CliError) {
      fail(e.message, e.exitCode)
    }
    throw e
  }

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    fail(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }

  if (mode === 'waves') {
    const { depth, finish } = computeSchedule(tasks, deps)
    const waves = new Map()
    for (const [name, d] of depth) {
      if (!waves.has(d)) waves.set(d, [])
      waves.get(d).push(name)
    }
    const maxWave = waves.size > 0 ? Math.max(...waves.keys()) : -1
    let out = ''
    for (let k = 0; k <= maxWave; k++) {
      const names = (waves.get(k) || []).slice().sort()
      out += `wave ${k}: ${names.join(' ')}\n`
    }
    let total = 0
    for (const f of finish.values()) if (f > total) total = f
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'explain') {
    const { depth, start, finish } = computeSchedule(tasks, deps)
    const names = [...tasks.keys()].sort()
    let out = ''
    for (const name of names) {
      out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    let total = 0
    for (const f of finish.values()) if (f > total) total = f
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'pack') {
    const { schedule, makespan } = pack(tasks, deps, workers)
    let out = ''
    for (let i = 0; i < workers; i++) {
      const parts = schedule[i].map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
      out += `worker ${i}:${parts}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

main()
"}

