const INTEGER = /^-?(?:0|[1-9][0-9]*)$/
const DURATION = /^([0-9]+)(ms|s|m|h)$/
const DURATION_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce one setting's raw text by its declared type, rendering it the way the specification asks.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text to coerce.
 * @returns {string} the rendered value.
 * @throws {ValueError} when the text does not fit the declared type.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!INTEGER.test(text)) throw new ValueError(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new ValueError(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new ValueError(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new ValueError(`${declared.key} is not a duration: ${text}`)
      return (BigInt(match[1]) * DURATION_MS[match[2]]).toString()
    }
    case 'list': {
      if (text === '') return ''
      const seen = new Set()
      const items = []
      for (const rawItem of text.split(',')) {
        const item = rawItem.trim()
        if (item === '') throw new ValueError(`${declared.key} has an empty item: ${text}`)
        if (!seen.has(item)) {
          seen.add(item)
          items.push(item)
        }
      }
      return items.join(',')
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}"}

