export class LexError extends Error {}

const isDigit = (c) => c >= '0' && c <= '9'
const isAlpha = (c) => (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
const isAlnum = (c) => isDigit(c) || isAlpha(c)

export function tokenize(s) {
  const toks = []
  let i = 0
  const n = s.length
  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (isDigit(c)) {
      let j = i + 1
      while (j < n && isDigit(s[j])) j++
      if (s[j] === '.' && isDigit(s[j + 1] || '')) {
        j++
        while (j < n && isDigit(s[j])) j++
      }
      toks.push({ type: 'NUM', value: s.slice(i, j) })
      i = j
      continue
    }
    if (isAlpha(c)) {
      let j = i + 1
      while (j < n && isAlnum(s[j])) j++
      toks.push({ type: 'IDENT', value: s.slice(i, j) })
      i = j
      continue
    }
    if (c === '(') {
      toks.push({ type: 'LP' })
      i++
      continue
    }
    if (c === ')') {
      toks.push({ type: 'RP' })
      i++
      continue
    }
    if (c === ',') {
      toks.push({ type: 'COMMA' })
      i++
      continue
    }
    if (c === ':') {
      toks.push({ type: 'COLON' })
      i++
      continue
    }
    if (c === '<') {
      if (s[i + 1] === '=') {
        toks.push({ type: 'OP', value: '<=' })
        i += 2
      } else if (s[i + 1] === '>') {
        toks.push({ type: 'OP', value: '<>' })
        i += 2
      } else {
        toks.push({ type: 'OP', value: '<' })
        i++
      }
      continue
    }
    if (c === '>') {
      if (s[i + 1] === '=') {
        toks.push({ type: 'OP', value: '>=' })
        i += 2
      } else {
        toks.push({ type: 'OP', value: '>' })
        i++
      }
      continue
    }
    if (c === '^' || c === '*' || c === '/' || c === '+' || c === '-' || c === '=') {
      toks.push({ type: 'OP', value: c })
      i++
      continue
    }
    throw new LexError(`unexpected character ${c}`)
  }
  toks.push({ type: 'EOF' })
  return toks
}
"}

