import { parseAddressStrict, numToCol } from './address.js'
import { parseFormula } from './parser.js'
import {
  numVal,
  errVal,
  isError,
  toNumber,
  toCondition,
  binOp,
  unaryOp,
  parseLiteral,
} from './values.js'

const KNOWN_FUNCTIONS = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
}

export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet
    this.memo = new Map()
    this.visiting = new Set()
  }

  getAst(cellInfo) {
    if (cellInfo.astComputed) return cellInfo.ast
    cellInfo.astComputed = true
    const body = cellInfo.content.slice(1)
    const parsed = parseFormula(body)
    cellInfo.ast = parsed.ok ? parsed.ast : null
    return cellInfo.ast
  }

  evalCell(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.visiting.has(key)) return errVal('#CYCLE!')
    const cellInfo = this.sheet.get(key)
    let result
    if (!cellInfo) {
      result = numVal(0)
      this.memo.set(key, result)
      return result
    }
    this.visiting.add(key)
    try {
      result = this.evalContent(cellInfo)
    } finally {
      this.visiting.delete(key)
    }
    this.memo.set(key, result)
    return result
  }

  evalContent(cellInfo) {
    const content = cellInfo.content
    if (content.startsWith('=')) {
      const ast = this.getAst(cellInfo)
      if (!ast) return errVal('#ERR!')
      return this.evalNode(ast)
    }
    return parseLiteral(content)
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return numVal(parseFloat(node.raw))
      case 'bool':
        return { t: 'bool', v: node.value }
      case 'address': {
        const info = parseAddressStrict(node.raw)
        if (!info) return errVal('#REF!')
        return this.evalCell(info.key)
      }
      case 'unary':
        return unaryOp(node.op, this.evalNode(node.operand))
      case 'binop':
        return binOp(node.op, this.evalNode(node.left), this.evalNode(node.right))
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  // Expand one function argument into its list of values (a range contributes
  // every cell it covers; anything else contributes exactly one value).
  expandArgValues(node) {
    if (node.type === 'range') {
      const a = parseAddressStrict(node.a)
      const b = parseAddressStrict(node.b)
      if (!a || !b) return [errVal('#REF!')]
      const colMin = Math.min(a.col, b.col)
      const colMax = Math.max(a.col, b.col)
      const rowMin = Math.min(a.row, b.row)
      const rowMax = Math.max(a.row, b.row)
      const vals = []
      for (let col = colMin; col <= colMax; col++) {
