      if (err) return err
      let count = 0
      for (const v of allVals) if (v.t === 'num') count++
      return numVal(count)
    }

    if (name === 'ABS') {
      const err = allVals.find(isError)
      if (err) return err
      if (allVals.length !== 1) return errVal('#VALUE!')
      const n = toNumber(allVals[0])
