      nums.push(n.v)
    }
    if (name === 'SUM') {
      const s = nums.reduce((a, b) => a + b, 0)
      return isFinite(s) ? numVal(s) : errVal('#DIV/0!')
    }
    if (name === 'MIN') return numVal(Math.min(...nums))
    if (name === 'MAX') return numVal(Math.max(...nums))
