// Every value that must stay exact (tokens, ticks) is kept as a BigInt.

export class BucketPolicy {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity // BigInt
    this.refill = refill // BigInt
    this.per = per // BigInt
    this.states = new Map() // key -> { scaled: BigInt, lastTick: BigInt }
  }

  advance(key, tick) {
    let state = this.states.get(key)
    const fullScaled = this.capacity * this.per
    if (!state) {
      state = { scaled: fullScaled, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.scaled += this.refill * elapsed
      if (state.scaled > fullScaled) state.scaled = fullScaled
      state.lastTick = tick
    }
  }

  allows(key) {
    const state = this.states.get(key)
    return state.scaled >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.scaled -= this.per
  }
}

export class WindowPolicy {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit // BigInt
    this.span = span // BigInt
    this.states = new Map() // key -> ticks array
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (!ticks) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    while (ticks.length > 0 && ticks[0] <= threshold) {
      ticks.shift()
    }
  }

  allows(key) {
    const ticks = this.states.get(key)
    return BigInt(ticks.length) < this.limit
  }

  record(key, tick) {
    const ticks = this.states.get(key)
    ticks.push(tick)
  }
}
"}

