// producing a per-event verdict trail and a per-key summary.

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) {
        best = route
      }
    }
  }
  return best
}

export function simulate({ policies, routes, events }) {
  const results = [] // { tick, key, allowed, deniedBy }
  const stats = new Map() // key -> { allowed, denied }

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    const policyList = route ? route.policyNames.map((n) => policies.get(n)) : []

    for (const policy of policyList) {
      policy.advance(key, tick)
    }

    let deniedBy = null
    for (let i = 0; i < policyList.length; i++) {
      if (!policyList[i].allows(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    const allowed = deniedBy === null
    if (allowed) {
      for (const policy of policyList) {
        if (policy instanceof Object && typeof policy.record === 'function') {
          if (policy.constructor.name === 'WindowPolicy') {
            policy.record(key, tick)
          } else {
            policy.record(key)
          }
        }
      }
    }

    results.push({ tick, key, allowed, deniedBy })

    let entry = stats.get(key)
    if (!entry) {
      entry = { allowed: 0, denied: 0 }
      stats.set(key, entry)
    }
    if (allowed) entry.allowed++
    else entry.denied++
  }

  return { results, stats }
}
"}

