{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-e42XoX/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { ParseError } from './errors.js'
import { parseProgram } from './parse.js'
import { simulate } from './simulate.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let program
  try {
    program = parseProgram(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { results, stats } = simulate(program)

  const lines = []
  if (mode === 'replay') {
    for (const r of results) {
      if (r.allowed) {
        lines.push(`${r.tick} ${r.key} allow`)
      } else {
        lines.push(`${r.tick} ${r.key} deny ${r.deniedBy}`)
      }
    }
  } else {
    const keys = [...stats.keys()].sort()
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const s = stats.get(key)
      totalAllowed += s.allowed
      totalDenied += s.denied
      lines.push(`${key} allowed=${s.allowed} denied=${s.denied}`)
    }
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

