{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-ewi7Lm/src/parser.js","content":"/**
 * Parses election input text into a structured election description:
 * { candidates: [name...], ballots: [{ count, names: [name...] }...] }
 *
 * Throws a ParseError carrying the message to print (already formatted,
 * without the leading "error: ") on any violation of the input format.
 */

export class ParseError extends Error {}

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export function parseElection(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidates = null // array of names, in declared order
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw new ParseError(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError(`line ${lineNo}: expected candidates <name>...`)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`line ${lineNo}: invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`line ${lineNo}: candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      for (const name of names) candidateSet.add(name)
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        throw new ParseError(`line ${lineNo}: expected ballot <count> <candidate>...`)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError(`line ${lineNo}: count must be a positive integer`)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`line ${lineNo}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`line ${lineNo}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

