{"file_path":"src/format.js","content":"/**
 * Rendering of a list of merge regions into the output for each CLI mode.
 */

/**
 * @param {Array<object>} regions as produced by buildRegions
 * @param {boolean} includeBase whether a conflict includes the ||||||| base section
 * @returns {{ text: string, hasConflict: boolean }}
 */
export function renderMerge(regions, includeBase) {
  const out = []
  let hasConflict = false
  for (const region of regions) {
    if (region.type === 'stable') {
      out.push(...region.lines)
    } else if (region.kind === 'conflict') {
      hasConflict = true
      out.push('<<<<<<< mine')
      out.push(...region.mineLines)
      if (includeBase) {
        out.push('||||||| base')
        out.push(...region.baseLines)
      }
      out.push('=======')
      out.push(...region.theirsLines)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  const text = out.length === 0 ? '' : out.join('\n') + '\n'
  return { text, hasConflict }
}

/**
 * @param {Array<object>} regions as produced by buildRegions
 * @returns {{ text: string, hasConflict: boolean }}
 */
export function renderRegions(regions) {
  const out = []
  let hasConflict = false
  for (const region of regions) {
    if (region.type === 'stable') {
      out.push(`stable ${region.lines.length}`)
    } else if (region.kind === 'conflict') {
      hasConflict = true
      out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  const text = out.length === 0 ? '' : out.join('\n') + '\n'
  return { text, hasConflict }
}
"}

