{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-nZvwR4/src/defs.js","content":"/** Parsing a stand-alone definitions file, one definition per line. */

import { splitLines } from './block.js'
import { normalizeLabel } from './label.js'

const DEFINITION = /^\[([^\]]+)\]:\s+(\S.*)$/u

/**
 * Parse a definitions file's text into a map of normalized label to url and source.
 * @param {string} text - the file's whole content.
 * @param {string} path - the file's path, named in any failure.
 * @returns {Map<string, {url: string, source: string}>} the definitions, keyed by normalized label.
 * @throws {Error} naming the file and the line, on a malformed line or a label defined twice.
 */
export function parseDefinitionsFile(text, path) {
  const definitions = new Map()
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index].trim()
    const line = index + 1
    if (raw === '' || raw.startsWith('#')) continue
    const match = DEFINITION.exec(raw)
    if (match === null) throw new Error(`${path}: line ${line}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) throw new Error(`${path}: line ${line}: label ${label} is defined twice`)
    definitions.set(label, { url: match[2], source: 'file' })
  }
  return definitions
}
"}

