{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-nZvwR4/src/cli.js","content":"#!/usr/bin/env node
/** The command: `html`, `outline`, and `defs`, each over the document on standard input, with an optional definitions file. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { parseDefinitionsFile } from './defs.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const defsPath = argv[1]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

let initialDefinitions = new Map()
if (defsPath !== undefined) {
  let text
  try {
    text = readFileSync(defsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${defsPath}`)
  }
  try {
    initialDefinitions = parseDefinitionsFile(text, defsPath)
  } catch (error) {
    fail(error.message)
  }
}

let blocks
let definitions
try {
  ;({ blocks, definitions } = parse(splitLines(readFileSync(0, 'utf8')), initialDefinitions))
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(blocks, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const entries = [...definitions.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  const lines = entries.map(([label, definition]) => `${label} ${definition.url} ${definition.source}\n`)
  process.stdout.write(`${lines.join('')}total ${entries.length}\n`)
}
"}

