{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-nq87a6/src/regions.js","content":"import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

function compose(base, start, end, changes) {
  const sorted = [...changes].sort((a, b) => a.baseStart - b.baseStart)
  const result = []
  let cursor = start
  for (const c of sorted) {
    if (c.baseStart > cursor) result.push(...base.slice(cursor, c.baseStart))
    result.push(...c.sideLines)
    cursor = c.baseEnd
  }
  if (cursor < end) result.push(...base.slice(cursor, end))
  return result
}

/**
 * Computes the ordered list of segments describing how to merge `mine` and
 * `theirs` against their common `base`. Each segment is either:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function computeSegments(mine, base, theirs) {
  const mineChanges = computeChanges(mine, base).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(theirs, base).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  let idx = 0
  while (idx < all.length) {
    const first = all[idx]
    const group = { start: first.baseStart, end: first.baseEnd, changes: [first] }
    idx++
    while (idx < all.length && all[idx].baseStart <= group.end) {
      group.changes.push(all[idx])
      group.end = Math.max(group.end, all[idx].baseEnd)
      idx++
    }
    groups.push(group)
  }

  const segments = []
  let cursor = 0
  for (const group of groups) {
    if (group.start > cursor) {
      segments.push({ kind: 'stable', lines: base.slice(cursor, group.start) })
    }

    const mineTouch = group.changes.filter(c => c.side === 'mine')
    const theirsTouch = group.changes.filter(c => c.side === 'theirs')

    const mineLines = compose(base, group.start, group.end, mineTouch)
    const theirsLines = compose(base, group.start, group.end, theirsTouch)
    const baseLines = base.slice(group.start, group.end)

    if (arraysEqual(mineLines, theirsLines)) {
      segments.push({ kind: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      segments.push({ kind: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      segments.push({ kind: 'mine', lines: mineLines })
    } else {
      segments.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = group.end
  }
  if (cursor < base.length) {
    segments.push({ kind: 'stable', lines: base.slice(cursor, base.length) })
  }

  return segments
}
"}

