  const lines = []
  lines.push('<<<<<<< mine')
  lines.push(...segment.mine)
  if (mode === 'merge') {
    lines.push('||||||| base')
    lines.push(...segment.base)
  }
  lines.push('=======')
  lines.push(...segment.theirs)
  lines.push('>>>>>>> theirs')
  return lines
}

function runMerge(mode, segments) {
  const outLines = []
  let conflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      conflict = true
      outLines.push(...renderConflict(mode, segment))
    } else {
      outLines.push(...segment.lines)
    }
  }
  return { conflict, text: outLines.length > 0 ? outLines.join('\n') + '\n' : '' }
}

function runRegions(segments) {
  const outLines = []
  let conflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      conflict = true
      outLines.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`)
    } else {
      outLines.push(`${segment.kind} ${segment.lines.length}`)
    }
  }
  return { conflict, text: outLines.length > 0 ? outLines.join('\n') + '\n' : '' }
}

function readStdin() {
  const chunks = []
  return new Promise((resolve, reject) => {
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
    process.exit(2)
  }

  const input = await readStdin()

  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseDocuments(input)
  } catch (err) {
    process.stderr.write(`${err.message}\n`)
    process.exit(2)
    return
  }

  const segments = computeSegments(mine, base, theirs)

  const { conflict, text } = mode === 'regions' ? runRegions(segments) : runMerge(mode, segments)

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

