{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-rFJdt4/src/policies.js","content":"/**
 * Token bucket and sliding window rate limiter policies. Each keeps one
 * independent state per key, created the first time that key reaches it.
 */

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.state = new Map()
  }

  // Tokens are tracked as an exact fraction with denominator `per`, stored
  // as the numerator (an integer number of "per"ths of a token). This keeps
  // all arithmetic exact, with no rounding of partial refill periods.
  advance(tick, key) {
    let s = this.state.get(key)
    if (!s) {
      s = { numerator: this.capacity * this.per, lastTick: tick }
      this.state.set(key, s)
      return
    }
    const dt = tick - s.lastTick
    if (dt > 0n) {
      const capNum = this.capacity * this.per
      let n = s.numerator + this.refill * dt
      if (n > capNum) n = capNum
      s.numerator = n
      s.lastTick = tick
    }
  }

  allows(key) {
    const s = this.state.get(key)
    return s.numerator >= this.per
  }

  record(key) {
    const s = this.state.get(key)
    s.numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  advance(tick, key) {
    let arr = this.state.get(key)
    if (!arr) {
      arr = []
      this.state.set(key, arr)
    }
    const threshold = tick - this.span
    let i = 0
    while (i < arr.length && arr[i] <= threshold) i++
    if (i > 0) arr.splice(0, i)
  }

  allows(key) {
    const arr = this.state.get(key)
    return BigInt(arr.length) < this.limit
  }

  record(key, tick) {
    this.state.get(key).push(tick)
  }
}
"}

