/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { simulate } from './simulate.js'
import { LineError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  // Synchronous read of fd 0, works for both pipes and files under node.
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let output
  try {
    output = simulate(mode, input)
  } catch (e) {
    if (e instanceof LineError) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

