  // caller already consumed as part of this same run. Returns the total
  // number of actual digits consumed (not counting underscores).
  consumeDigitRun(isDigit, initialCount) {
    let count = initialCount
    for (;;) {
      const c = this.peek()
      if (c !== undefined && isDigit(c)) {
        this.advance()
        count++
        continue
      }
      if (c === '_' && count > 0 && isDigit(this.peek(1))) {
        this.advance()
        continue
      }
      break
    }
    return count
  }

  skipWhitespaceAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === undefined) return
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (this.peek() !== undefined && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const start = this.here()
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.peek() === undefined) {
            throw new LexError('unterminated block comment', start.line, start.col)
          }
          if (this.peek() === '/' && this.peek(1) === '*') {
            this.advance()
            this.advance()
            depth++
            continue
          }
          if (this.peek() === '*' && this.peek(1) === '/') {
            this.advance()
            this.advance()
            depth--
            continue
          }
          this.advance()
        }
        continue
      }
      return
    }
  }

  scanNumber() {
    const start = this.here()
    const startPos = this.pos
    let prefixInvalid = false

    const first = this.advance()
    if (first === '0' && (this.peek() === 'x' || this.peek() === 'X')) {
      this.advance()
      const count = this.consumeDigitRun(isHexDigit, 0)
      if (count === 0) prefixInvalid = true
    } else if (first === '0' && (this.peek() === 'b' || this.peek() === 'B')) {
      this.advance()
      const count = this.consumeDigitRun(isBinDigit, 0)
      if (count === 0) prefixInvalid = true
    } else if (first === '0' && (this.peek() === 'o' || this.peek() === 'O')) {
      this.advance()
      const count = this.consumeDigitRun(isOctDigit, 0)
      if (count === 0) prefixInvalid = true
    } else {
      this.consumeDigitRun(isDecDigit, 1)
      if (this.peek() === '.' && isDecDigit(this.peek(1))) {
        this.advance()
        this.consumeDigitRun(isDecDigit, 0)
      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        const n1 = this.peek(1)
        let validExp = false
        if (isDecDigit(n1)) validExp = true
        else if ((n1 === '+' || n1 === '-') && isDecDigit(this.peek(2))) validExp = true
        if (validExp) {
          this.advance()
          if (this.peek() === '+' || this.peek() === '-') this.advance()
          this.consumeDigitRun(isDecDigit, 0)
        }
      }
    }

    let trailingInvalid = false
    while (this.peek() !== undefined && isIdentContinue(this.peek())) {
      this.advance()
      trailingInvalid = true
    }

    const text = this.textSince(startPos)
    if (prefixInvalid || trailingInvalid) {
      throw new LexError(`invalid number ${text}`, start.line, start.col)
    }
    return { kind: 'number', text, line: start.line, col: start.col }
  }

  scanIdent() {
    const start = this.here()
    let text = this.advance()
    while (this.peek() !== undefined && isIdentContinue(this.peek())) text += this.advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, line: start.line, col: start.col }
  }

  scanString() {
    const start = this.here()
    this.advance() // opening quote
    let value = ''
    for (;;) {
      const c = this.peek()
      if (c === undefined) throw new LexError('unterminated string', start.line, start.col)
      if (c === '\n') {
        const pos = this.here()
        throw new LexError('newline in string', pos.line, pos.col)
      }
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\\') {
        const backslashPos = this.here()
        this.advance() // backslash
        const esc = this.peek()
        if (esc === undefined) throw new LexError('unterminated string', start.line, start.col)
        switch (esc) {
          case 'n':
            this.advance()
            value += '\n'
            break
          case 't':
            this.advance()
            value += '\t'
            break
          case 'r':
            this.advance()
            value += '\r'
            break
          case '\\':
            this.advance()
            value += '\\'
            break
          case '"':
            this.advance()
            value += '"'
            break
          case '0':
            this.advance()
            value += '\0'
            break
          case 'x': {
            this.advance() // 'x'
            const h1 = this.peek()
            const h2 = this.peek(1)
            if (!isHexDigit(h1) || !isHexDigit(h2)) {
              throw new LexError('invalid escape \\x', backslashPos.line, backslashPos.col)
            }
            this.advance()
            this.advance()
            value += String.fromCharCode(parseInt(h1 + h2, 16))
            break
          }
          case 'u': {
            this.advance() // 'u'
            if (this.peek() !== '{') {
              throw new LexError('invalid escape \\u', backslashPos.line, backslashPos.col)
            }
            this.advance() // '{'
            let hex = ''
            while (this.peek() !== undefined && isHexDigit(this.peek())) hex += this.advance()
            if (hex.length === 0 || this.peek() !== '}') {
              throw new LexError('invalid escape \\u', backslashPos.line, backslashPos.col)
            }
            this.advance() // '}'
            const cp = parseInt(hex, 16)
            if (cp > 0x10ffff) {
              throw new LexError('invalid escape \\u', backslashPos.line, backslashPos.col)
            }
            value += String.fromCodePoint(cp)
            break
          }
          default:
            throw new LexError(`invalid escape \\${esc}`, backslashPos.line, backslashPos.col)
        }
        continue
      }
      value += this.advance()
    }
    return { kind: 'string', text: JSON.stringify(value), line: start.line, col: start.col }
  }

  scanRawString() {
    const start = this.here()
    this.advance() // 'r'
    this.advance() // '"'
    let value = ''
    for (;;) {
      const c = this.peek()
      if (c === undefined) throw new LexError('unterminated string', start.line, start.col)
      if (c === '"') {
        this.advance()
        break
      }
      value += this.advance()
    }
    return { kind: 'rawstring', text: JSON.stringify(value), line: start.line, col: start.col }
  }

  scanPunctOrError() {
    const start = this.here()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (TWO_CHAR_PUNCT.has(two)) {
      this.advance()
      this.advance()
      return { kind: 'punct', text: two, line: start.line, col: start.col }
    }
    const c = this.peek()
    if (ONE_CHAR_PUNCT.has(c)) {
      this.advance()
      return { kind: 'punct', text: c, line: start.line, col: start.col }
    }
    this.advance()
    throw new LexError(`unexpected character ${c}`, start.line, start.col)
  }
}

export function tokenize(source) {
  const scanner = new Scanner(source)
  const tokens = []
  for (;;) {
    scanner.skipWhitespaceAndComments()
    const c = scanner.peek()
    if (c === undefined) break
    if (isDecDigit(c)) {
      tokens.push(scanner.scanNumber())
    } else if (c === '"') {
      tokens.push(scanner.scanString())
    } else if (c === 'r' && scanner.peek(1) === '"') {
      tokens.push(scanner.scanRawString())
    } else if (isIdentStart(c)) {
      tokens.push(scanner.scanIdent())
    } else {
      tokens.push(scanner.scanPunctOrError())
    }
  }
  return tokens
}
"}

