/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { tokenize, LexError } from './lexer.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const mode = args[0]

  const source = require('node:fs').readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) {
      out += `${t.line}:${t.col} ${t.kind} ${t.text}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    let out = ''
    for (const k of KIND_ORDER) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
  process.exit(0)
}

main()
"}

