import { IniError } from './ini.js'
import { SETTINGS, envName } from './schema.js'

const BY_NAME = new Map(SETTINGS.map(declared => [envName(declared.key), declared.key]))

/** The 1-based column of the first non-space character of `raw`. */
function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * The column a value was written at: its first character, or, when the value
 * is empty, one past the line's last non-space character.
 * @param {string} raw - the raw line.
 * @param {number} base - the raw column of the first character after `=`.
 * @param {string} valuePart - the text after `=`, untrimmed.
 * @param {string} text - `valuePart` trimmed.
 * @returns {number} the 1-based column.
 */
function valueColumn(raw, base, valuePart, text) {
  if (text === '') return raw.trimEnd().length + 1
  return base + (valuePart.length - valuePart.trimStart().length)
}

/**
 * Parse the environment layer.
 * @param {string} text - the whole standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each recognised setting's
 *   raw value, its line, and the column its value was written at.
 * @throws {IniError} on the first line the grammar refuses, at its first non-space character.
 */
export function parseEnv(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const pos = indent(raw)
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, pos, 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new IniError(line, pos, 'expected a variable name')
    const key = BY_NAME.get(name)
    if (key === undefined) throw new IniError(line, pos, `unknown environment variable ${name}`)
    if (values.has(key)) throw new IniError(line, pos, `${name} is set twice`)
    const valuePart = trimmed.slice(split + 1)
    const value = valuePart.trim()
    const column = valueColumn(raw, indent(raw) + split + 1, valuePart, value)
    values.set(key, { text: value, line, column })
  }
  return values
}
"}

