{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986,
 * as specified by the task prompt.
 */

class UriError extends Error {}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

function asciiLower(s) {
  let out = ''
  for (const ch of s) {
    const cp = ch.codePointAt(0)
    if (cp >= 65 && cp <= 90) {
      out += String.fromCharCode(cp + 32)
    } else {
      out += ch
    }
  }
  return out
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isUnreservedByte(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

/** Uppercase %XX escapes and decode the ones that spell an unreserved byte. */
function normalizePercent(str, componentName) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const h1 = str[i + 1]
      const h2 = str[i + 2]
      if (h1 === undefined || h2 === undefined || !isHexDigit(h1) || !isHexDigit(h2)) {
        throw new UriError(`the ${componentName} has a truncated percent-encoding`)
      }
      const hex = (h1 + h2).toUpperCase()
      const code = parseInt(hex, 16)
      if (isUnreservedByte(code)) {
        out += String.fromCharCode(code)
      } else {
        out += '%' + hex
      }
      i += 2
    } else {
      out += c
    }
  }
  return out
}

/**
 * Split raw authority text into userinfo, host and port pieces, per the
 * generic-syntax rules stated in the prompt. Presence flags distinguish an
 * absent piece from an empty one.
 */
function splitAuthority(authority) {
  let userinfo = null
  let hasUserinfo = false
  let hostPort = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    hasUserinfo = true
    userinfo = authority.slice(0, atIdx)
    hostPort = authority.slice(atIdx + 1)
  }
  const bracketIdx = hostPort.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = hostPort.indexOf(':', searchFrom)
  let host, port, hasPort
  if (colonIdx !== -1) {
    hasPort = true
    host = hostPort.slice(0, colonIdx)
    port = hostPort.slice(colonIdx + 1)
  } else {
    hasPort = false
    port = null
    host = hostPort
  }
  return { userinfo, hasUserinfo, host, port, hasPort }
}

/** Parse a URI reference into its generic-syntax components. */
function parseReference(str) {
  let rest = str
  let hasScheme = false
  let scheme = null

  let colonIdx = -1
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === ':') {
      colonIdx = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIdx !== -1) {
    hasScheme = true
    scheme = str.slice(0, colonIdx)
    rest = str.slice(colonIdx + 1)
  }

  let hasAuthority = false
  let userinfo = null
  let hasUserinfo = false
  let host = ''
  let port = null
  let hasPort = false
  if (rest.startsWith('//')) {
    hasAuthority = true
    let j = 2
    while (j < rest.length && rest[j] !== '/' && rest[j] !== '?' && rest[j] !== '#') j++
    const authority = rest.slice(2, j)
    rest = rest.slice(j)
    const split = splitAuthority(authority)
    userinfo = split.userinfo
    hasUserinfo = split.hasUserinfo
    host = split.host
    port = split.port
    hasPort = split.hasPort
  }

  let k = 0
  while (k < rest.length && rest[k] !== '?' && rest[k] !== '#') k++
  const path = rest.slice(0, k)
  rest = rest.slice(k)

  let hasQuery = false
  let query = null
  if (rest.startsWith('?')) {
    hasQuery = true
    let m = 1
    while (m < rest.length && rest[m] !== '#') m++
    query = rest.slice(1, m)
    rest = rest.slice(m)
  }

  let hasFragment = false
  let fragment = null
  if (rest.startsWith('#')) {
    hasFragment = true
    fragment = rest.slice(1)
  }

  return {
    hasScheme,
    scheme,
    hasAuthority,
    hasUserinfo,
    userinfo,
    host,
    hasPort,
    port,
    path,
    hasQuery,
    query,
    hasFragment,
    fragment,
  }
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx = 0
      if (input[0] === '/') idx = 1
      while (idx < input.length && input[idx] !== '/') idx++
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }
  return output
}

/** Merge a reference path onto a base's path per RFC 3986 section 5.2.3. */
function mergePaths(base, refPath) {
  if (base.hasAuthority && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Apply the normalization procedure to a set of parsed components,
 * mutating and returning it. Throws UriError (without "line N:" prefix) on
 * a truncated percent-encoding, checking path, userinfo, host, query and
 * fragment in that order.
 */
function normalizeComponents(c) {
  if (c.hasScheme) {
    c.scheme = asciiLower(c.scheme)
  }

  c.path = normalizePercent(c.path, 'path')
  if (c.hasUserinfo) {
    c.userinfo = normalizePercent(c.userinfo, 'userinfo')
  }
  if (c.hasAuthority) {
    c.host = normalizePercent(c.host, 'host')
  }
  if (c.hasQuery) {
    c.query = normalizePercent(c.query, 'query')
  }
  if (c.hasFragment) {
    c.fragment = normalizePercent(c.fragment, 'fragment')
  }

  if (c.hasAuthority) {
    c.host = asciiLower(c.host)
  }

  if (c.hasPort) {
    const def = c.hasScheme ? DEFAULT_PORTS[c.scheme] : undefined
    if (c.port === '' || (def !== undefined && c.port === def)) {
      c.hasPort = false
      c.port = null
    }
  }

  c.path = removeDotSegments(c.path)

  if (c.hasAuthority && c.path === '') {
    c.path = '/'
  }

  return c
}

function serialize(c) {
  let out = ''
  if (c.hasScheme) out += c.scheme + ':'
  if (c.hasAuthority) {
    let authority = ''
    if (c.hasUserinfo) authority += c.userinfo + '@'
    authority += c.host
    if (c.hasPort) authority += ':' + c.port
    out += '//' + authority
  }
  out += c.path
  if (c.hasQuery) out += '?' + c.query
  if (c.hasFragment) out += '#' + c.fragment
  return out
}

/** Parse, normalize and serialize a single URI reference. */
function normalizeReference(str) {
  const c = parseReference(str)
  normalizeComponents(c)
  return serialize(c)
}

/** Resolve reference `refStr` against base `baseStr`, then normalize. */
function resolveReference(baseStr, refStr) {
  const base = parseReference(baseStr)
  if (!base.hasScheme) {
    throw new UriError('the base has no scheme')
  }
  const ref = parseReference(refStr)

  const t = {}

  function takeFromRef() {
    t.hasAuthority = ref.hasAuthority
    t.hasUserinfo = ref.hasUserinfo
    t.userinfo = ref.userinfo
    t.host = ref.host
    t.hasPort = ref.hasPort
    t.port = ref.port
    t.path = removeDotSegments(ref.path)
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  }

  function takeAuthorityFromBase() {
    t.hasAuthority = base.hasAuthority
    t.hasUserinfo = base.hasUserinfo
    t.userinfo = base.userinfo
    t.host = base.host
    t.hasPort = base.hasPort
    t.port = base.port
  }

  if (ref.hasScheme) {
    t.hasScheme = true
    t.scheme = ref.scheme
    takeFromRef()
  } else if (ref.hasAuthority) {
    t.hasScheme = true
    t.scheme = base.scheme
    takeFromRef()
  } else if (ref.path === '') {
    t.hasScheme = true
    t.scheme = base.scheme
    takeAuthorityFromBase()
    t.path = base.path
    if (ref.hasQuery) {
      t.hasQuery = true
      t.query = ref.query
    } else {
      t.hasQuery = base.hasQuery
      t.query = base.query
    }
  } else {
    t.hasScheme = true
    t.scheme = base.scheme
    if (ref.path.startsWith('/')) {
      t.path = removeDotSegments(ref.path)
    } else {
      t.path = removeDotSegments(mergePaths(base, ref.path))
    }
    takeAuthorityFromBase()
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  }

  t.hasFragment = ref.hasFragment
  t.fragment = ref.fragment

  normalizeComponents(t)
  return serialize(t)
}

module.exports = { UriError, normalizeReference, resolveReference }
"}

