{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { UriError, normalizeReference, resolveReference } from './uri.js'

function readStdin() {
  const chunks = []
  return new Promise((resolve, reject) => {
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
    return
  }
  const mode = args[0]

  const input = await readStdin()
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeReference(line))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const base = line.slice(0, spaceIdx)
        const ref = line.slice(spaceIdx + 1)
        results.push(resolveReference(base, ref))
      }
    } catch (err) {
      if (err instanceof UriError) {
        fail(`line ${lineNo}: ${err.message}`)
        return
      }
      throw err
    }
  }

  if (results.length > 0) {
    process.stdout.write(results.join('\n') + '\n')
  }
  process.exit(0)
}

main()
"}

